<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">grid-template-columns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: repeat(</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auto-fill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, minmax(250px, 1fr));</span></span>
